 19 │ // defaultRiskMaxEntities bounds a changeset report. The command is intended to
 20 │ // make a review decision promptly, not to turn one large diff into unbounded
 21 │ // repeated graph traversals.
 22 │ const defaultRiskMaxEntities = 5
 23 │ 
 24 │ type riskLevel string
 25 │ 
 26 │ const (
 27 │ 	riskHigh   riskLevel = "high"
 28 │ 	riskMedium riskLevel = "medium"
 29 │ 	riskLow    riskLevel = "low"
 30 │ )
