 32 │ type riskFlags struct {
 33 │ 	Repo        string
 34 │ 	Base        string
 35 │ 	Head        string
 36 │ 	Checkpoint  string
 37 │ 	Format      string
 38 │ 	Profile     string
 39 │ 	MaxEntities int
 40 │ }
