 42 │ type riskEvidence struct {
 43 │ 	DirectCallers     int                `json:"direct_callers"`
 44 │ 	TransitiveCallers int                `json:"transitive_callers"`
 45 │ 	TypeConsumers     int                `json:"type_consumers"`
 46 │ 	Callees           int                `json:"callees"`
 47 │ 	TopCallers        []neighborEndpoint `json:"top_callers"`
 48 │ }
