 50 │ type riskEntry struct {
 51 │ 	Name            string       `json:"name"`
 52 │ 	Kind            string       `json:"kind"`
 53 │ 	ChangeType      string       `json:"change_type"`
 54 │ 	FilePath        string       `json:"file_path,omitempty"`
 55 │ 	StartLine       int          `json:"start_line,omitempty"`
 56 │ 	DependentsCount int          `json:"dependents_count"`
 57 │ 	Level           riskLevel    `json:"level"`
 58 │ 	Evidence        riskEvidence `json:"graph_evidence"`
 59 │ 	Tests           []string     `json:"affected_tests"`
 60 │ 	Inference       string       `json:"inference"`
 61 │ 	Limitations     []string     `json:"limitations,omitempty"`
 62 │ }
 63 │ 
 64 │ type riskReport struct {
 65 │ 	FormatVersion    int                   `json:"format_version"`
 66 │ 	Base             string                `json:"base,omitempty"`
 67 │ 	Head             string                `json:"head,omitempty"`
 68 │ 	Checkpoint       string                `json:"checkpoint,omitempty"`
 69 │ 	OverallRisk      riskLevel             `json:"overall_risk"`
 70 │ 	EntitiesChanged  int                   `json:"entities_changed"`
 71 │ 	EntitiesAnalyzed int                   `json:"entities_analyzed"`
 72 │ 	EntitiesSkipped  int                   `json:"entities_skipped,omitempty"`
 73 │ 	Entries          []riskEntry           `json:"entries"`
 74 │ 	RecommendedTests []string              `json:"recommended_tests"`
 75 │ 	Warnings         []sem.ProviderWarning `json:"warnings,omitempty"`
 76 │ 	Limitations      []string              `json:"limitations,omitempty"`
 77 │ }
