 79 │ func parseRiskFlags(args []string) (riskFlags, error) {
 80 │ 	flags := riskFlags{Base: "HEAD~1", Head: "HEAD", Format: "text", Profile: "full", MaxEntities: defaultRiskMaxEntities}
 81 │ 	baseSet, headSet := false, false
 82 │ 	for i := 0; i < len(args); i++ {
 83 │ 		arg := args[i]
 84 │ 		value := func() (string, error) {
 85 │ 			i++
 86 │ 			if i >= len(args) {
 87 │ 				return "", fmt.Errorf("%s requires a value", arg)
 88 │ 			}
 89 │ 			return args[i], nil
 90 │ 		}
 91 │ 		switch arg {
 92 │ 		case "--repo":
 93 │ 			item, err := value()
 94 │ 			if err != nil {
 95 │ 				return flags, err
 96 │ 			}
 97 │ 			flags.Repo = item
 98 │ 		case "--base":
 99 │ 			item, err := value()
100 │ 			if err != nil {
101 │ 				return flags, err
102 │ 			}
103 │ 			if err := validateRevision("--base", item); err != nil {
104 │ 				return flags, err
105 │ 			}
106 │ 			flags.Base, baseSet = item, true
107 │ 		case "--head":
108 │ 			item, err := value()
109 │ 			if err != nil {
110 │ 				return flags, err
111 │ 			}
112 │ 			if err := validateRevision("--head", item); err != nil {
113 │ 				return flags, err
114 │ 			}
115 │ 			flags.Head, headSet = item, true
116 │ 		case "--checkpoint":
117 │ 			item, err := value()
118 │ 			if err != nil {
119 │ 				return flags, err
120 │ 			}
121 │ 			if strings.TrimSpace(item) == "" {
122 │ 				return flags, errors.New("--checkpoint requires a value")
123 │ 			}
124 │ 			flags.Checkpoint = item
125 │ 		case "--format":
126 │ 			item, err := value()
127 │ 			if err != nil {
128 │ 				return flags, err
129 │ 			}
130 │ 			flags.Format = item
131 │ 		case "--profile":
132 │ 			item, err := value()
133 │ 			if err != nil {
134 │ 				return flags, err
135 │ 			}
136 │ 			flags.Profile = item
137 │ 		case "--max-entities":
138 │ 			item, err := value()
139 │ 			if err != nil {
140 │ 				return flags, err
141 │ 			}
142 │ 			count, parseErr := strconv.Atoi(item)
143 │ 			if parseErr != nil || count <= 0 {
144 │ 				return flags, fmt.Errorf("--max-entities requires a positive integer, got %q", item)
145 │ 			}
146 │ 			flags.MaxEntities = count
147 │ 		default:
148 │ 			return flags, fmt.Errorf("risk received unexpected argument %q", arg)
149 │ 		}
150 │ 	}
151 │ 	if flags.Checkpoint != "" && (baseSet || headSet) {
152 │ 		return flags, errors.New("risk --checkpoint cannot be combined with --base or --head")
153 │ 	}
154 │ 	if flags.Format != "text" && flags.Format != "json" {
155 │ 		return flags, fmt.Errorf("risk --format must be text or json, got %q", flags.Format)
156 │ 	}
157 │ 	return flags, nil
158 │ }
159 │ 
160 │ func runRisk(ctx context.Context, opts Options, args []string) error {
161 │ 	flags, err := parseRiskFlags(args)
162 │ 	if err != nil {
163 │ 		return err
164 │ 	}
165 │ 	repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
166 │ 	if err != nil {
167 │ 		return err
168 │ 	}
169 │ 	profile, err := parseProfile(flags.Profile)
170 │ 	if err != nil {
171 │ 		return err
172 │ 	}
173 │ 
174 │ 	var diff sem.Result
175 │ 	if flags.Checkpoint != "" {
176 │ 		diff, err = sem.AnalyzeCheckpoint(ctx, repo, flags.Checkpoint)
177 │ 	} else {
178 │ 		// Match the normal diff command's default budget. The report preserves
179 │ 		// the semantic diff's explicit budget warning rather than silently
180 │ 		// treating a partial result as a complete changeset.
181 │ 		diff, err = sem.AnalyzeGitRangeWithOptions(ctx, repo, flags.Base, flags.Head, nil, sem.AnalyzeOptions{
182 │ 			MaxDuration: time.Duration(defaultMaxSeconds) * time.Second,
183 │ 		})
184 │ 	}
185 │ 	if err != nil {
186 │ 		return err
187 │ 	}
188 │ 	// A range describes committed trees, so build the same committed current-tree
189 │ 	// view used by normal head-mode graph queries. A non-HEAD range is still
190 │ 	// reported honestly; symbol resolution may be incomplete if its head is not
191 │ 	// the checkout's current committed tree.
192 │ 	snapshot, _, err := sem.LoadOrBuildProviderSnapshot(ctx, repo, opts.Version, sem.ProviderSnapshotOptions{
193 │ 		NoNetwork: true, Worktree: false, Profile: profile,
194 │ 	}, resolveCacheDir("", opts.Env.PluginDataDir), false)
195 │ 	if err != nil {
196 │ 		return err
197 │ 	}
198 │ 	readSource, closeSource := openSnapshotLineReaderOrDegrade(ctx, snapshot, false, opts.Stderr)
199 │ 	if closeSource != nil {
200 │ 		defer closeSource()
201 │ 	}
202 │ 	evidenceAvailable, evidenceLimitation := riskEvidenceMatchesHead(ctx, repo, flags.Head, snapshot)
203 │ 	report := buildRiskReport(diff, snapshot, flags, readSource, evidenceAvailable, evidenceLimitation)
204 │ 	if flags.Checkpoint != "" {
205 │ 		report.Checkpoint = flags.Checkpoint
206 │ 		report.Limitations = append(report.Limitations, "checkpoint impact evidence is resolved against the current committed checkout; verify it if the checkpoint commit is not checked out")
207 │ 	} else {
208 │ 		report.Base, report.Head = flags.Base, flags.Head
209 │ 	}
210 │ 	if profile != sem.ProfileFull {
211 │ 		report.Limitations = append(report.Limitations, "the selected graph profile may omit relationship families; use --profile full for the most complete risk evidence")
212 │ 	}
213 │ 	switch flags.Format {
214 │ 	case "json":
215 │ 		encoder := json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout))
216 │ 		encoder.SetEscapeHTML(false)
217 │ 		return encoder.Encode(report)
218 │ 	case "text":
219 │ 		return writeRiskText(opts.Stdout, report)
220 │ 	default:
221 │ 		return fmt.Errorf("risk --format must be text or json, got %q", flags.Format)
222 │ 	}
223 │ }
224 │ 
225 │ // riskEvidenceMatchesHead prevents a range from being paired with graph data
226 │ // from another committed tree. Provider snapshots can only describe the
227 │ // current checkout, so a non-current --head must not borrow its callers or
228 │ // type consumers as evidence.
229 │ func riskEvidenceMatchesHead(ctx context.Context, repo, head string, snapshot sem.ProviderSnapshot) (bool, string) {
230 │ 	if snapshot.Header.Tree == "" {
231 │ 		return false, "graph evidence was omitted because the current committed snapshot has no tree provenance"
232 │ 	}
233 │ 	requestedTree, err := gitutil.RevParse(ctx, repo, head+"^{tree}")
234 │ 	if err != nil {
235 │ 		return false, "graph evidence was omitted because the requested --head tree could not be resolved against the current committed snapshot"
236 │ 	}
237 │ 	if requestedTree != snapshot.Header.Tree {
238 │ 		return false, "graph evidence was omitted because the requested --head is not the current committed checkout; check out that revision before analyzing its callers or type consumers"
239 │ 	}
240 │ 	return true, ""
241 │ }
