248 │ func buildRiskReport(diff sem.Result, snapshot sem.ProviderSnapshot, flags riskFlags, readSource lineReader, evidenceAvailable bool, evidenceLimitation string) riskReport {
249 │ 	report := riskReport{FormatVersion: 1, OverallRisk: riskLow, Entries: []riskEntry{}, RecommendedTests: []string{}, Warnings: append([]sem.ProviderWarning{}, diff.Warnings...)}
250 │ 	report.Warnings = append(report.Warnings, snapshot.Header.Warnings...)
251 │ 	if !evidenceAvailable && evidenceLimitation != "" {
252 │ 		report.Limitations = append(report.Limitations, evidenceLimitation)
253 │ 	}
254 │ 	var changes []riskChangedEntity
255 │ 	for _, file := range diff.Files {
256 │ 		for _, change := range file.Changes {
257 │ 			path := change.NewPath
258 │ 			if path == "" {
259 │ 				path = file.Path
260 │ 			}
261 │ 			if path == "" {
262 │ 				path = change.OldPath
263 │ 			}
264 │ 			changes = append(changes, riskChangedEntity{change: change, path: path})
265 │ 		}
266 │ 	}
267 │ 	report.EntitiesChanged = len(changes)
268 │ 	sort.SliceStable(changes, func(i, j int) bool {
269 │ 		if changes[i].change.DependentsCount != changes[j].change.DependentsCount {
270 │ 			return changes[i].change.DependentsCount > changes[j].change.DependentsCount
271 │ 		}
272 │ 		if changes[i].path != changes[j].path {
273 │ 			return changes[i].path < changes[j].path
274 │ 		}
275 │ 		return changes[i].change.Name < changes[j].change.Name
276 │ 	})
277 │ 	if len(changes) > flags.MaxEntities {
278 │ 		report.EntitiesSkipped = len(changes) - flags.MaxEntities
279 │ 		changes = changes[:flags.MaxEntities]
280 │ 		report.Limitations = append(report.Limitations, fmt.Sprintf("analysis is capped at %d entities; %d lower-priority entity changes were skipped", flags.MaxEntities, report.EntitiesSkipped))
281 │ 	}
282 │ 	tests := map[string]bool{}
283 │ 	for _, item := range changes {
284 │ 		entry := buildRiskEntry(snapshot, item, readSource, evidenceAvailable, evidenceLimitation)
285 │ 		for _, test := range entry.Tests {
286 │ 			tests[test] = true
287 │ 		}
288 │ 		report.Entries = append(report.Entries, entry)
289 │ 	}
290 │ 	report.EntitiesAnalyzed = len(report.Entries)
291 │ 	for test := range tests {
292 │ 		report.RecommendedTests = append(report.RecommendedTests, test)
293 │ 	}
294 │ 	sort.Strings(report.RecommendedTests)
295 │ 	report.OverallRisk = classifyChangesetRisk(report.Entries)
296 │ 	if len(snapshot.Header.PartialFailures) > 0 {
297 │ 		report.Limitations = append(report.Limitations, "the graph reported partial parse/index failures; inspect the evidence before relying on a complete blast radius")
298 │ 	}
299 │ 	if report.EntitiesChanged == 0 {
300 │ 		report.Limitations = append(report.Limitations, "no semantic entity changes were detected")
301 │ 	}
302 │ 	return report
303 │ }
