305 │ func buildRiskEntry(snapshot sem.ProviderSnapshot, item riskChangedEntity, readSource lineReader, evidenceAvailable bool, evidenceLimitation string) riskEntry {
306 │ 	change := item.change
307 │ 	name := change.NewName
308 │ 	if name == "" {
309 │ 		name = change.Name
310 │ 	}
311 │ 	if name == "" {
312 │ 		name = change.OldName
313 │ 	}
314 │ 	line := change.AfterStartLine
315 │ 	if line == 0 {
316 │ 		line = change.BeforeStartLine
317 │ 	}
318 │ 	entry := riskEntry{Name: name, Kind: change.Kind, ChangeType: change.Type, FilePath: item.path, StartLine: line, DependentsCount: change.DependentsCount, Tests: []string{}}
319 │ 	if !evidenceAvailable {
320 │ 		entry.Limitations = append(entry.Limitations, evidenceLimitation)
321 │ 		entry.Level = classifyEntityRisk(change, riskEvidence{})
322 │ 		entry.Inference = riskInference(change, entry.Level, riskEvidence{})
323 │ 		return entry
324 │ 	}
325 │ 	impact := buildImpactResponseFromReader(snapshot, impactFlags{Symbol: name, File: item.path, Line: line, Kind: change.Kind, Depth: 2, Limit: defaultImpactSectionLimit}, readSource)
326 │ 	if impact.Focus == nil || impact.DisambiguationRequired {
327 │ 		if impact.DisambiguationRequired {
328 │ 			entry.Limitations = append(entry.Limitations, "graph symbol resolution is ambiguous; no blast radius was inferred")
329 │ 		} else {
330 │ 			entry.Limitations = append(entry.Limitations, "changed symbol is absent from the current graph snapshot (commonly an added, removed, or non-current-range entity)")
331 │ 		}
332 │ 		entry.Level = classifyEntityRisk(change, riskEvidence{})
333 │ 		entry.Inference = riskInference(change, entry.Level, riskEvidence{})
334 │ 		return entry
335 │ 	}
336 │ 	annotateImpactCallSites(&impact, readSource)
337 │ 	evidence := riskEvidence{DirectCallers: impact.Callers.Direct, TransitiveCallers: impact.Callers.Transitive, TypeConsumers: impact.TypeConsumers.Total, Callees: impact.Callees.Total, TopCallers: []neighborEndpoint{}}
338 │ 	for _, caller := range impact.Callers.Entries {
339 │ 		evidence.TopCallers = append(evidence.TopCallers, caller.Endpoint)
340 │ 	}
341 │ 	entry.Evidence = evidence
342 │ 	entry.Tests = collectAffectedTests(impact)
343 │ 	entry.Level = classifyEntityRisk(change, evidence)
344 │ 	entry.Inference = riskInference(change, entry.Level, evidence)
345 │ 	if impact.Degenerate {
346 │ 		entry.Limitations = append(entry.Limitations, impact.DegenerateReason)
347 │ 	}
348 │ 	if len(impact.PartialFailures) > 0 {
349 │ 		entry.Limitations = append(entry.Limitations, "graph evidence is incomplete because this snapshot has partial failures")
350 │ 	}
351 │ 	return entry
352 │ }
