354 │ // classifyEntityRisk is deliberately deterministic and conservative. Graph
355 │ // counts are evidence; the verdict below is the tool's inference from them.
356 │ func classifyEntityRisk(change sem.EntityChange, evidence riskEvidence) riskLevel {
357 │ 	if evidence.DirectCallers >= 10 || evidence.TypeConsumers >= 10 || (change.Type == "signature_changed" && evidence.DirectCallers >= 5) || (change.Type == "removed" && change.DependentsCount >= 5) {
358 │ 		return riskHigh
359 │ 	}
360 │ 	if evidence.DirectCallers > 0 || evidence.TypeConsumers > 0 || change.DependentsCount > 0 || change.Type == "signature_changed" || change.Type == "removed" {
361 │ 		return riskMedium
362 │ 	}
363 │ 	return riskLow
364 │ }
