366 │ func classifyChangesetRisk(entries []riskEntry) riskLevel {
367 │ 	level := riskLow
368 │ 	for _, entry := range entries {
369 │ 		if entry.Level == riskHigh {
370 │ 			return riskHigh
371 │ 		}
372 │ 		if entry.Level == riskMedium {
373 │ 			level = riskMedium
374 │ 		}
375 │ 	}
376 │ 	return level
377 │ }
