379 │ func collectAffectedTests(impact impactResponse) []string {
380 │ 	seen := map[string]bool{}
381 │ 	collect := func(section impactSection) {
382 │ 		for _, item := range section.Entries {
383 │ 			if isConventionalTestPath(item.Endpoint.FilePath) {
384 │ 				seen[item.Endpoint.FilePath] = true
385 │ 			}
386 │ 		}
387 │ 	}
388 │ 	collect(impact.Callers)
389 │ 	collect(impact.CoChanges)
390 │ 	tests := make([]string, 0, len(seen))
391 │ 	for path := range seen {
392 │ 		tests = append(tests, path)
393 │ 	}
394 │ 	sort.Strings(tests)
395 │ 	return tests
396 │ }
