398 │ func riskInference(change sem.EntityChange, level riskLevel, evidence riskEvidence) string {
399 │ 	if evidence.DirectCallers > 0 {
400 │ 		return fmt.Sprintf("%s change with %d direct graph caller%s and %d type consumer%s → %s risk.", change.Type, evidence.DirectCallers, plural(evidence.DirectCallers), evidence.TypeConsumers, plural(evidence.TypeConsumers), strings.ToUpper(string(level)))
401 │ 	}
402 │ 	if change.DependentsCount > 0 {
403 │ 		return fmt.Sprintf("%s change has %d semantic-diff dependent%s but no resolved current-snapshot callers → %s risk.", change.Type, change.DependentsCount, plural(change.DependentsCount), strings.ToUpper(string(level)))
404 │ 	}
405 │ 	return fmt.Sprintf("%s change has no resolved graph callers or dependents → %s risk.", change.Type, strings.ToUpper(string(level)))
406 │ }
