415 │ func writeRiskText(out io.Writer, report riskReport) error {
416 │ 	out = termsafe.NewWriter(out)
417 │ 	fmt.Fprintf(out, "CHANGESET RISK: %s %s  (%d entities changed, %d analyzed)\n", strings.ToUpper(string(report.OverallRisk)), riskIcon(report.OverallRisk), report.EntitiesChanged, report.EntitiesAnalyzed)
418 │ 	if report.Checkpoint != "" {
419 │ 		fmt.Fprintf(out, "Checkpoint: %s\n", report.Checkpoint)
420 │ 	} else {
421 │ 		fmt.Fprintf(out, "Base: %s  Head: %s\n", report.Base, report.Head)
422 │ 	}
423 │ 	if len(report.Entries) == 0 {
424 │ 		fmt.Fprintln(out, "No semantic entity changes detected.")
425 │ 	}
426 │ 	for _, entry := range report.Entries {
427 │ 		fmt.Fprintf(out, "\n%s %s  %s [%s]\n", riskIcon(entry.Level), strings.ToUpper(string(entry.Level)), entry.Name, entry.ChangeType)
428 │ 		if entry.FilePath != "" {
429 │ 			fmt.Fprintf(out, "  Evidence location: %s:%d (%s)\n", entry.FilePath, entry.StartLine, entry.Kind)
430 │ 		}
431 │ 		fmt.Fprintln(out, "  Graph evidence:")
432 │ 		fmt.Fprintf(out, "    %d direct callers, %d transitive callers, %d type consumers, %d callees\n", entry.Evidence.DirectCallers, entry.Evidence.TransitiveCallers, entry.Evidence.TypeConsumers, entry.Evidence.Callees)
433 │ 		for _, caller := range entry.Evidence.TopCallers {
434 │ 			fmt.Fprintf(out, "    - %s:%d  %s\n", caller.FilePath, caller.StartLine, caller.Name)
435 │ 		}
436 │ 		fmt.Fprintf(out, "  Our inference: %s\n", entry.Inference)
437 │ 		for _, limitation := range entry.Limitations {
438 │ 			fmt.Fprintf(out, "  Limitation: %s\n", limitation)
439 │ 		}
440 │ 	}
441 │ 	fmt.Fprintf(out, "\nRECOMMENDED TESTS (%d files, from graph caller/co-change relationships)\n", len(report.RecommendedTests))
442 │ 	for _, test := range report.RecommendedTests {
443 │ 		fmt.Fprintf(out, "  %s\n", test)
444 │ 	}
445 │ 	if len(report.RecommendedTests) > 0 {
446 │ 		fmt.Fprintln(out, "  Verify by running the relevant test files; recommendations are path-based, not coverage-based.")
447 │ 	}
448 │ 	if len(report.Warnings) > 0 {
449 │ 		fmt.Fprintln(out, "\nWARNINGS")
450 │ 		for _, warning := range report.Warnings {
451 │ 			fmt.Fprintf(out, "  %s", warning.Code)
452 │ 			if warning.FilePath != "" {
453 │ 				fmt.Fprintf(out, " %s", warning.FilePath)
454 │ 			}
455 │ 			if warning.EffectOnCompleteness != "" {
456 │ 				fmt.Fprintf(out, " (%s)", warning.EffectOnCompleteness)
457 │ 			}
458 │ 			if warning.Detail != "" {
459 │ 				fmt.Fprintf(out, ": %s", warning.Detail)
460 │ 			}
461 │ 			fmt.Fprintln(out)
462 │ 		}
463 │ 	}
464 │ 	for _, limitation := range report.Limitations {
465 │ 		fmt.Fprintf(out, "Limitation: %s\n", limitation)
466 │ 	}
467 │ 	return nil
468 │ }
