 79 │ func parseRiskFlags(args []string) (riskFlags, error) {
 80 │ 	flags := riskFlags{Base: "HEAD~1", Head: "HEAD", Format: "text", Profile: "full", MaxEntities: defaultRiskMaxEntities}
 81 │ 	baseSet, headSet := false, false
 82 │ 	for i := 0; i < len(args); i++ {
 83 │ 		arg := args[i]
 84 │ 		value := func() (string, error) {
 85 │ 			i++
 86 │ 			if i >= len(args) {
 87 │ 				return "", fmt.Errorf("%s requires a value", arg)
 88 │ 			}
 89 │ 			return args[i], nil
 90 │ 		}
 91 │ 		switch arg {
 92 │ 		case "--repo":
 93 │ 			item, err := value()
 94 │ 			if err != nil {
 95 │ 				return flags, err
 96 │ 			}
 97 │ 			flags.Repo = item
 98 │ 		case "--base":
 99 │ 			item, err := value()
100 │ 			if err != nil {
101 │ 				return flags, err
102 │ 			}
103 │ 			if err := validateRevision("--base", item); err != nil {
104 │ 				return flags, err
105 │ 			}
106 │ 			flags.Base, baseSet = item, true
107 │ 		case "--head":
108 │ 			item, err := value()
109 │ 			if err != nil {
110 │ 				return flags, err
111 │ 			}
112 │ 			if err := validateRevision("--head", item); err != nil {
113 │ 				return flags, err
114 │ 			}
115 │ 			flags.Head, headSet = item, true
116 │ 		case "--checkpoint":
117 │ 			item, err := value()
118 │ 			if err != nil {
119 │ 				return flags, err
120 │ 			}
121 │ 			if strings.TrimSpace(item) == "" {
122 │ 				return flags, errors.New("--checkpoint requires a value")
123 │ 			}
124 │ 			flags.Checkpoint = item
125 │ 		case "--format":
126 │ 			item, err := value()
127 │ 			if err != nil {
128 │ 				return flags, err
129 │ 			}
130 │ 			flags.Format = item
131 │ 		case "--profile":
132 │ 			item, err := value()
133 │ 			if err != nil {
134 │ 				return flags, err
135 │ 			}
136 │ 			flags.Profile = item
137 │ 		case "--max-entities":
138 │ 			item, err := value()
139 │ 			if err != nil {
140 │ 				return flags, err
141 │ 			}
142 │ 			count, parseErr := strconv.Atoi(item)
143 │ 			if parseErr != nil || count <= 0 {
144 │ 				return flags, fmt.Errorf("--max-entities requires a positive integer, got %q", item)
145 │ 			}
146 │ 			flags.MaxEntities = count
147 │ 		default:
148 │ 			return flags, fmt.Errorf("risk received unexpected argument %q", arg)
149 │ 		}
150 │ 	}
151 │ 	if flags.Checkpoint != "" && (baseSet || headSet) {
152 │ 		return flags, errors.New("risk --checkpoint cannot be combined with --base or --head")
153 │ 	}
154 │ 	if flags.Format != "text" && flags.Format != "json" {
155 │ 		return flags, fmt.Errorf("risk --format must be text or json, got %q", flags.Format)
156 │ 	}
157 │ 	return flags, nil
158 │ }
