225 │ // riskEvidenceMatchesHead prevents a range from being paired with graph data
226 │ // from another committed tree. Provider snapshots can only describe the
227 │ // current checkout, so a non-current --head must not borrow its callers or
228 │ // type consumers as evidence.
229 │ func riskEvidenceMatchesHead(ctx context.Context, repo, head string, snapshot sem.ProviderSnapshot) (bool, string) {
230 │ 	if snapshot.Header.Tree == "" {
231 │ 		return false, "graph evidence was omitted because the current committed snapshot has no tree provenance"
232 │ 	}
233 │ 	requestedTree, err := gitutil.RevParse(ctx, repo, head+"^{tree}")
234 │ 	if err != nil {
235 │ 		return false, "graph evidence was omitted because the requested --head tree could not be resolved against the current committed snapshot"
236 │ 	}
237 │ 	if requestedTree != snapshot.Header.Tree {
238 │ 		return false, "graph evidence was omitted because the requested --head is not the current committed checkout; check out that revision before analyzing its callers or type consumers"
239 │ 	}
240 │ 	return true, ""
241 │ }
