// P1: degenerate verdict never reaches the risk report (risk.go never calls
// impactDegenerateReason, which analyzeImpact does at impact.go:205).
func TestProbeP1DegenerateNeverSurfaces(t *testing.T) {
	// Focus resolves, but has zero relations -> impactDegenerateReason() == no relations.
	snapshot := sem.ProviderSnapshot{Symbols: []sem.SymbolRecord{
		{ID: "lonely", Name: "Lonely", Kind: "function", FilePath: "a.go", StartLine: 1},
