func TestProbeP3MismatchedHeadReportsLowWithZeroEvidence(t *testing.T) {
	syms := []sem.SymbolRecord{{ID: "t", Name: "Target", Kind: "function", FilePath: "s.go", StartLine: 1}}
	var rels []sem.RelationRecord
	for i := 0; i < 40; i++ {
		id := "c" + string(rune('a'+i%26)) + string(rune('a'+i/26))
