		rels = append(rels, sem.RelationRecord{Type: "CALLS", FromID: id, ToID: "t"})
	}
	snapshot := sem.ProviderSnapshot{Symbols: syms, Relations: rels}
	diff := sem.Result{Files: []sem.FileChange{{Path: "s.go", Changes: []sem.EntityChange{
		{Name: "Target", Kind: "function", Type: "body_changed", AfterStartLine: 1, NewPath: "s.go"},
	}}}}

	avail := buildRiskReport(diff, snapshot, riskFlags{MaxEntities: 5}, nil, true, "")
	t.Logf("evidence AVAILABLE: level=%s direct=%d overall=%s",
		avail.Entries[0].Level, avail.Entries[0].Evidence.DirectCallers, avail.OverallRisk)

	omitted := buildRiskReport(diff, snapshot, riskFlags{MaxEntities: 5}, nil, false, "graph evidence was omitted because the requested --head is not the current committed checkout")
	e := omitted.Entries[0]
	t.Logf("evidence OMITTED:   level=%s direct=%d overall=%s inference=%q", e.Level, e.Evidence.DirectCallers, omitted.OverallRisk, e.Inference)
	if avail.Entries[0].Level != riskHigh {
		t.Fatalf("probe setup: expected high with evidence, got %s", avail.Entries[0].Level)
	}
	if e.Level != riskLow || omitted.OverallRisk != riskLow {
		t.Fatalf("REFUTED: omitted-evidence entry was not LOW: %s / %s", e.Level, omitted.OverallRisk)
	}
	t.Log("CONFIRMED: 40-caller symbol reported overall_risk=low, graph_evidence all zeros")
}

// P4: overall_risk is computed only from the surviving (capped) entries.
func TestProbeP4OverallRiskFromTruncatedSubset(t *testing.T) {
	syms := []sem.SymbolRecord{{ID: "z", Name: "ZHot", Kind: "function", FilePath: "z.go", StartLine: 1}}
	var rels []sem.RelationRecord
	changes := []sem.EntityChange{}
	for i := 0; i < 40; i++ {
		id := "k" + string(rune('a'+i%26)) + string(rune('a'+i/26))
		syms = append(syms, sem.SymbolRecord{ID: id, Name: "K" + id, Kind: "function", FilePath: "z.go", StartLine: 50 + i})
		rels = append(rels, sem.RelationRecord{Type: "CALLS", FromID: id, ToID: "z"})
	}
	// Six cold entities in files sorting before z.go, plus the hot one.
	for _, n := range []string{"a", "b", "c", "d", "e", "f"} {
		syms = append(syms, sem.SymbolRecord{ID: n, Name: "Cold" + n, Kind: "function", FilePath: n + ".go", StartLine: 1})
		changes = append(changes, sem.EntityChange{Name: "Cold" + n, Kind: "function", Type: "body_changed", AfterStartLine: 1, NewPath: n + ".go"})
	}
	changes = append(changes, sem.EntityChange{Name: "ZHot", Kind: "function", Type: "body_changed", AfterStartLine: 1, NewPath: "z.go"})

	files := []sem.FileChange{}
	for _, c := range changes {
		files = append(files, sem.FileChange{Path: c.NewPath, Changes: []sem.EntityChange{c}})
	}
	snapshot := sem.ProviderSnapshot{Symbols: syms, Relations: rels}
	report := buildRiskReport(sem.Result{Files: files}, snapshot, riskFlags{MaxEntities: defaultRiskMaxEntities}, nil, true, "")
	names := []string{}
	for _, e := range report.Entries {
		names = append(names, string(e.Level)+":"+e.Name)
	}
	t.Logf("changed=%d analyzed=%d skipped=%d overall=%s entries=%v",
		report.EntitiesChanged, report.EntitiesAnalyzed, report.EntitiesSkipped, report.OverallRisk, names)
	if report.OverallRisk != riskLow {
		t.Fatalf("REFUTED: overall risk was %s, not low", report.OverallRisk)
	}
	t.Log("CONFIRMED: 40-caller ZHot dropped by the cap; headline reads CHANGESET RISK: LOW")
}

